import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, mix, sin, fract, dot, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Texture } = THREE;

  const colors = (config.intent?.visualSpec?.colors) ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'features-card-3';

  const content = new Group();
  root.add(content);

  // --- Depth plane 1: backing plate (adds edge depth, avoids flat void) ---
  const backGeo = new PlaneGeometry(1.9, 2.3);
  const backMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.6,
    metalness: 0.3,
  });
  const backing = new Mesh(backGeo, backMat);
  backing.position.z = -0.04;
  content.add(backing);

  // --- Depth plane 2: main brushed-metal card surface ---
  const cardGeo = new PlaneGeometry(1.8, 2.2);
  const cardMat = new MeshPhysicalNodeMaterial({
    roughness: 0.52,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
  });

  const placeholderTex = new Texture();
  const texNode = texture(placeholderTex);

  const uvN = uv();
  const gradient = mix(tslColor(colors.surface), tslColor(colors.ink), uvN.y);
  const grain = fract(sin(dot(uvN.mul(937.0), vec2(12.9898, 78.233))).mul(43758.5453));
  const grainCentered = grain.sub(0.5).mul(0.035);
  const base = mix(gradient, texNode.rgb, 0.65);
  cardMat.colorNode = base.add(grainCentered);

  const card = new Mesh(cardGeo, cardMat);
  card.position.z = 0;
  content.add(card);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace ?? tex.colorSpace;
    texNode.value = tex;
    cardMat.needsUpdate = true;
  }).catch(() => {});

  // --- Depth plane 3: accent inset detail (<=10% of frame area) ---
  const accentGeo = new PlaneGeometry(1.4, 0.04);
  const accentMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.0,
    roughness: 0.4,
    metalness: 0.2,
  });
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(0, -0.95, 0.02);
  content.add(accentLine);

  // --- Node-local rim light (opposite key, carries accent hue) ---
  const rim = new THREE.DirectionalLight(colors.accent, 0.7);
  rim.position.set(-1.2, 0.6, 1.6);
  content.add(rim);

  // no cinematicPrimitives configured for this node — none applied by spec

  // --- Motion: weighted-settle entrance + subtle idle breathing (no interactivity) ---
  content.position.y += 0.2;
  content.scale.setScalar(0.98);
  cardMat.transparent = true;
  backMat.transparent = true;
  accentMat.transparent = true;
  cardMat.opacity = 0;
  backMat.opacity = 0;
  accentMat.opacity = 0;

  const tl = gsap.timeline({
    onComplete: () => {
      idleTl.play();
    },
  });
  tl.to(content.position, { y: content.position.y - 0.2, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to([cardMat, backMat, accentMat], { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  tl.to(content.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' }, 0.1);
  tl.to(content.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.5);

  const idleTl = gsap.timeline({ paused: true, repeat: -1, yoyo: true });
  idleTl.to(content.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 3.2, ease: 'sine.inOut' });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    idleTl.kill();

    backGeo.dispose();
    cardGeo.dispose();
    accentGeo.dispose();

    backMat.dispose();
    cardMat.dispose();
    accentMat.dispose();

    if (placeholderTex) placeholderTex.dispose();
    if (texNode.value && texNode.value.dispose) texNode.value.dispose();

    content.remove(rim);
    content.clear();
    root.clear();
  };

  return root;
}
